set -eu
tag="v$(python -c 'import codejig; print(codejig.VERSION)')"
bin=$(find "$(npm root -g)/@openai" -type f -name codex -size +10M | head -1)
codex_home="$RUNNER_TEMP/codex home $1"
curl -fsSL "http://127.0.0.1:8765/v/$tag/bootstrap.py" | python3 -I - --base-url http://127.0.0.1:8765/v \
  --version "$tag" --overlay-dir "$RUNNER_TEMP/codex overlay $1" --codex-home "$codex_home" --codex-bin "$bin"
head -n 1 "$codex_home/AGENTS.md" | grep -q '^<!-- generated by code-jig'
"$HOME/.local/bin/code-jig" --codex-home "$codex_home" doctor --check-binary --codex-bin "$bin"
"$HOME/.local/bin/cjig" --help
